func DoDeadlock() {
log.Println("DoDeadlock invoked")
ch := make(chan struct{})
<-ch // blocks forever
}

func TestAllGoRoutinesFinished(t *testing.T) {
var wg sync.WaitGroup
wg.Go(DoNoDeadlock)
wg.Go(DoDeadlock)
wg.Wait()
}

func TestAllGoRoutinesFinishedSynctest(t *testing.T) {
synctest.Test(t, func(t *testing.T) {
go DoNoDeadlock()
go DoNoDeadlock()
})
}

func TestListenAndServe(t *testing.T) {
synctest.Test(t, func(t *testing.T) {
go http.ListenAndServe(":8080", nil)
})
}
// Will hang because http.ListenAndServe is waiting on I/O.

func TestWorkerProcessesItem(t *testing.T) {
synctest.Test(t, func(t *testing.T) {
var processed int
ch := make(chan int, 1)
defer close(ch)
go func() {
for i := range ch {
processed = i
}
}()
ch <- 42
synctest.Wait()
if processed != 42 {
t.Fatalf("expected 42, got %d", processed)
}
})
}

func Retry(f func() error, n int, interval time.Duration) error {
var err error
for range n {
if err = f(); err != nil {
time.Sleep(interval)
} else {
return nil
}
}
return fmt.Errorf("failed to execute the function after %d tries. Last
error: %s", n, err.Error())
}

func TestRetrySynctest(t *testing.T) {
synctest.Test(t, func(t *testing.T) {
f := func() error { return errors.New("error") }
var err error
go func() {
err = Retry(f, 3, time.Second*10)
}()
time.Sleep(30 * time.Second)
synctest.Wait() // prevents race
if err == nil {
t.Fatal("Retry was expected to fail after 30 seconds")
}
})
}
